import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";

export default function CardVoiture({ color = "light" }) {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchCars = async () => {
    try {
      setLoading(true);
      const res = await getAllCars();
      setCars(res.data);
    } catch (err) {
      setError("Erreur lors du chargement");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm("Confirmer la suppression ?")) {
      try {
        await deleteCarById(id);
        fetchCars();
      } catch (err) {
        setError("Erreur de suppression");
        console.error(err);
      }
    }
  };

  useEffect(() => { fetchCars(); }, []);

  if (loading) return <div className="text-center py-8">Chargement...</div>;
  if (error) return <div className="text-center py-8 text-red-500">{error}</div>;

  return (
    <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${
      color === "light" ? "bg-white" : "bg-blueGray-900 text-white"
    }`}>
      <div className="rounded-t mb-0 px-4 py-3 border-0">
        <div className="flex flex-wrap items-center">
          <div className="relative w-full px-4 max-w-full flex-grow flex-1">
            <h3 className={`font-semibold text-lg ${
              color === "light" ? "text-blueGray-700" : "text-white"
            }`}>
              Liste des Voitures
            </h3>
          </div>
          <div>
            <Link to="/admin/AddVoiture">
              <button className="bg-green-500 text-white text-sm px-4 py-2 rounded shadow">
                ➕ Ajouter
              </button>
            </Link>
          </div>
        </div>
      </div>

      <div className="block w-full overflow-x-auto">
        <table className="items-center w-full bg-transparent border-collapse">
          <thead>
            <tr>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Modèle</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Marque</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Matricule</th>
              <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Prix/jour</th>
              <th className="px-6 py-3 text-center text-xs font-semibold uppercase">Actions</th>
            </tr>
          </thead>
          <tbody>
            {cars.map((car) => (
              <tr key={car._id}>
                <td className="px-6 py-4 text-sm">{car.model}</td>
                <td className="px-6 py-4 text-sm">{car.marque}</td>
                <td className="px-6 py-4 text-sm">{car.matricule}</td>
                <td className="px-6 py-4 text-sm">{car.prix_jour} €</td>
                <td className="px-6 py-4 text-center">
                  <div className="flex gap-2 justify-center">
                    <Link to={{ 
                      pathname: `/admin/UpdateVoiture/${car._id}`,
                      state: { car }
                    }}>
                      <button className="bg-blue-500 text-white text-xs px-3 py-1 rounded shadow">
                        ✏️ Modifier
                      </button>
                    </Link>
                    <button
                      onClick={() => handleDelete(car._id)}
                      className="bg-red-500 text-white text-xs px-3 py-1 rounded shadow"
                    >
                      🗑️ Supprimer
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
